"""显式 HTTP 操作归属；新增路由必须同步登记并通过完整性测试。"""


def permission_for_view(view, action, method=None, data=None):
    view_type = view if isinstance(view, type) else type(view)
    view_key = f'{view_type.__module__}.{view_type.__name__}'
    if method:
        required = HTTP_PERMISSION_RULES.get((view_key, action, method.lower()))
    else:
        matches = [value for (owner, operation, _), value in HTTP_PERMISSION_RULES.items()
                   if owner == view_key and operation == action]
        required = matches[0] if matches and all(value == matches[0] for value in matches) else None
    if not required:
        return None
    if view_key == 'src.apps.auto_pytest.api.views.pytest_repository.PytestRepositoryViews' and action == 'save_repository':
        return 'pytest.repository:change' if (data or {}).get('id') else 'pytest.repository:add'
    return required

def _option_permissions(*pages):
    """显式登记使用选项的业务菜单；查看、新建和编辑窗口均可加载选项。"""
    return tuple(f'{page}:{operation}' for page in pages for operation in ('read', 'add', 'change'))


